-- Marketplace (tablas, permisos y controles DV)
USE [FGF-BDD];
GO
IF OBJECT_ID('dbo.Producto','U') IS NULL
BEGIN
 CREATE TABLE dbo.Producto(IdProducto int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Producto PRIMARY KEY, Nombre nvarchar(max) NOT NULL, Descripcion nvarchar(max) NOT NULL, Precio decimal(10,2) NOT NULL, Stock int NOT NULL, Imagen nvarchar(max) NULL, Activo bit NOT NULL CONSTRAINT DF_Producto_Activo DEFAULT(1), DV_Horizontal varchar(max) NULL, CONSTRAINT CK_Producto_Precio CHECK(Precio>=0), CONSTRAINT CK_Producto_Stock CHECK(Stock>=0));
END;
IF OBJECT_ID('dbo.CarritoItem','U') IS NULL
BEGIN
 CREATE TABLE dbo.CarritoItem(IdItem int IDENTITY(1,1) NOT NULL CONSTRAINT PK_CarritoItem PRIMARY KEY, DNI nvarchar(8) NOT NULL, IdProducto int NOT NULL, Cantidad int NOT NULL, DV_Horizontal varchar(max) NULL, CONSTRAINT UQ_CarritoItem_Cliente_Producto UNIQUE(DNI,IdProducto), CONSTRAINT CK_CarritoItem_Cantidad CHECK(Cantidad>0), CONSTRAINT FK_CarritoItem_Usuario FOREIGN KEY(DNI) REFERENCES dbo.Usuario(dni), CONSTRAINT FK_CarritoItem_Producto FOREIGN KEY(IdProducto) REFERENCES dbo.Producto(IdProducto));
END;
IF OBJECT_ID('dbo.Compra','U') IS NULL
BEGIN
 CREATE TABLE dbo.Compra(IdCompra int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Compra PRIMARY KEY, DNI nvarchar(8) NOT NULL, Fecha datetime NOT NULL, Total decimal(10,2) NOT NULL, Estado nvarchar(30) NOT NULL, TitularTarjeta nvarchar(256) NOT NULL, Ultimos4 nvarchar(100) NOT NULL, DV_Horizontal varchar(max) NULL, CONSTRAINT FK_Compra_Usuario FOREIGN KEY(DNI) REFERENCES dbo.Usuario(dni));
END;
IF OBJECT_ID('dbo.CompraItem','U') IS NULL
BEGIN
 CREATE TABLE dbo.CompraItem(IdCompraItem int IDENTITY(1,1) NOT NULL CONSTRAINT PK_CompraItem PRIMARY KEY, IdCompra int NOT NULL, IdProducto int NULL, NombreProducto nvarchar(max) NOT NULL, PrecioUnitario decimal(10,2) NOT NULL, Cantidad int NOT NULL, DV_Horizontal varchar(max) NULL, CONSTRAINT FK_CompraItem_Compra FOREIGN KEY(IdCompra) REFERENCES dbo.Compra(IdCompra), CONSTRAINT FK_CompraItem_Producto FOREIGN KEY(IdProducto) REFERENCES dbo.Producto(IdProducto) ON DELETE SET NULL);
END;
IF NOT EXISTS(SELECT 1 FROM dbo.Permiso WHERE nombre=N'ProductoGestionar') INSERT dbo.Permiso(nombre,descripcion) VALUES(N'ProductoGestionar',N'Gestionar productos del marketplace');
DECLARE @Permiso int=(SELECT id_permiso FROM dbo.Permiso WHERE nombre=N'ProductoGestionar');
DELETE rp FROM dbo.RolPermiso rp INNER JOIN dbo.Rol r ON r.id_rol=rp.id_rol WHERE rp.id_permiso=@Permiso AND r.nombre<>N'Admin';
INSERT dbo.RolPermiso(id_rol,id_permiso) SELECT id_rol,@Permiso FROM dbo.Rol WHERE nombre=N'Admin' AND NOT EXISTS(SELECT 1 FROM dbo.RolPermiso rp WHERE rp.id_rol=dbo.Rol.id_rol AND rp.id_permiso=@Permiso);
IF NOT EXISTS(SELECT 1 FROM dbo.DigitoVerificador WHERE NombreTabla=N'Producto') INSERT dbo.DigitoVerificador(NombreTabla,DigitoVertical,CantidadRegistros) VALUES(N'Producto',N'0',0);
IF NOT EXISTS(SELECT 1 FROM dbo.DigitoVerificador WHERE NombreTabla=N'CarritoItem') INSERT dbo.DigitoVerificador(NombreTabla,DigitoVertical,CantidadRegistros) VALUES(N'CarritoItem',N'0',0);
IF NOT EXISTS(SELECT 1 FROM dbo.DigitoVerificador WHERE NombreTabla=N'Compra') INSERT dbo.DigitoVerificador(NombreTabla,DigitoVertical,CantidadRegistros) VALUES(N'Compra',N'0',0);
IF NOT EXISTS(SELECT 1 FROM dbo.DigitoVerificador WHERE NombreTabla=N'CompraItem') INSERT dbo.DigitoVerificador(NombreTabla,DigitoVertical,CantidadRegistros) VALUES(N'CompraItem',N'0',0);
GO

