DELETE tr FROM dbo.Traduccion tr JOIN dbo.Etiqueta e ON e.IdEtiqueta=tr.IdEtiqueta WHERE e.Formulario=N'Carrito.aspx' AND e.ControlId IN(N'btnQuitar',N'msgProductoQuitado',N'gvCarrito_Header_Precio');
DELETE FROM dbo.Etiqueta WHERE Formulario=N'Carrito.aspx' AND ControlId IN(N'btnQuitar',N'msgProductoQuitado',N'gvCarrito_Header_Precio');
DELETE tr FROM dbo.Traduccion tr JOIN dbo.Etiqueta e ON e.IdEtiqueta=tr.IdEtiqueta WHERE e.Formulario=N'Carrito.aspx' AND e.ControlId IN(N'litPagoNotaTitulo',N'litNotaPago');
DELETE FROM dbo.Etiqueta WHERE Formulario=N'Carrito.aspx' AND ControlId IN(N'litPagoNotaTitulo',N'litNotaPago');

INSERT INTO dbo.Etiqueta(Formulario,ControlId)
SELECT src.Formulario,src.ControlId FROM @Etiquetas src
WHERE NOT EXISTS(SELECT 1 FROM dbo.Etiqueta e WHERE e.Formulario=src.Formulario AND e.ControlId=src.ControlId);

INSERT INTO dbo.Traduccion(IdIdioma,IdEtiqueta,Texto)
SELECT i.IdIdioma,e.IdEtiqueta,t.Texto
FROM @Etiquetas x
JOIN dbo.Etiqueta e ON e.Formulario=x.Formulario AND e.ControlId=x.ControlId
CROSS JOIN (VALUES(N'es-AR'),(N'en-US')) c(Codigo)
JOIN dbo.Idioma i ON i.Codigo=c.Codigo
CROSS APPLY (VALUES(CASE c.Codigo WHEN N'es-AR' THEN x.TextoEs ELSE x.TextoEn END)) t(Texto)
WHERE NOT EXISTS(SELECT 1 FROM dbo.Traduccion tr WHERE tr.IdIdioma=i.IdIdioma AND tr.IdEtiqueta=e.IdEtiqueta);


UPDATE tr SET Texto=CASE i.Codigo WHEN N'es-AR' THEN x.TextoEs ELSE x.TextoEn END
FROM dbo.Traduccion tr
JOIN dbo.Etiqueta e ON e.IdEtiqueta=tr.IdEtiqueta
JOIN @Etiquetas x ON x.Formulario=e.Formulario AND x.ControlId=e.ControlId
JOIN dbo.Idioma i ON i.IdIdioma=tr.IdIdioma;

