IF OBJECT_ID(N'dbo.Atencion', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.Atencion
    (
        id_atencion INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Atencion PRIMARY KEY,
        id_consulta INT NOT NULL,
        diagnostico NVARCHAR(MAX) NULL,
        observaciones NVARCHAR(MAX) NULL,
        atendido BIT NOT NULL CONSTRAINT DF_Atencion_Atendido DEFAULT (0),
        DV_Horizontal VARCHAR(MAX) NULL,
        CONSTRAINT FK_Atencion_Consulta FOREIGN KEY (id_consulta) REFERENCES dbo.Consulta(idConsulta)
    );
END;

